theorem pair_mem_of_mem_pairRows {α : Type*}
    {H : Hypergraph α} {E : Row α} (hE : E ∈ pairRows H) :
    E ∈ H ∧ E.card = 2

theorem pair_eq_pair_of_mem {α : Type*} [DecidableEq α]
    {E : Row α} {p : α} (hEcard : E.card = 2) (hpE : p ∈ E) :
    ∃ q, p ≠ q ∧ E = {p, q}

theorem triple_reorder {α : Type*} [DecidableEq α]
    (A B C : Row α) :
    ({A, B, C} : Hypergraph α) = {B, C, A}

theorem three_pair_graph_classification {α : Type*}
    [DecidableEq α]
    {H : Hypergraph α}
    (hPairRowsCard : (pairRows H).card = 3) :
    HasPairGraphP4 H ∨ HasPairGraphP3K2 H ∨
      HasPairGraphThreeK2 H ∨ HasPairGraphK3 H ∨ HasPairGraphK13 H

theorem pair_blocker_support_union {α : Type*}
    [Fintype α] [DecidableEq α]
    {K : Hypergraph α} {x y : α}
    (hPair : ({x, y} : Row α) ∈ blocker K) :
    pointSupport K x ∪ pointSupport K y = K

theorem exists_row_avoiding_nonblocker_pair {α : Type*}
    [Fintype α] [DecidableEq α]
    {K : Hypergraph α} {x y : α}
    (hBRows : RowsCardAtLeast (blocker K) 2)
    (hNotPair : ({x, y} : Row α) ∉ blocker K) :
    ∃ E ∈ K, x ∉ E ∧ y ∉ E

theorem blocker_restrictRows_lift {α : Type*}
    [Fintype α] [DecidableEq α]
    {K : Hypergraph α} {V T : Row α}
    (hTV : T ⊆ V) (hT : T ∈ blocker (restrictRows K V)) :
    T ∈ blocker K

theorem blocker_degree_ge_of_restriction {α : Type*}
    [Fintype α] [DecidableEq α]
    {K H : Hypergraph α} {V : Row α} {x : α}
    (hLift : ∀ T ∈ blocker (restrictRows K V), T ∈ H)
    (hDegree : 4 ≤ degree (blocker (restrictRows K V)) x) :
    4 ≤ degree H x

theorem pair_mem_blocker_of_transversal {α : Type*}
    [Fintype α] [DecidableEq α]
    {K : Hypergraph α} {x y : α}
    (hBRows : RowsCardAtLeast (blocker K) 2)
